mapper.select:
select sum(allocation_num)
from ${tableName}
where enterprise_code = #{enterpriseCode}
  and process_main_id = #{processMainId}
  and delete_flag = false

select *
from ${tableName}
where enterprise_code = #{enterpriseCode}
  and delete_flag = false
  and batch_no = #{batchNo}
  and inspect_user_code = #{inspectUserCode} limit 1

with t as( select process_main_id,inspect_type,inspect_ratio,should_inspect_num, sum(allocation_num) as allocation_num from ${dispatcherTableName} GROUP BY process_main_id,inspect_type,inspect_ratio,should_inspect_num ) select a.primary_key as primaryKeyValue,a.batch_num,a.procedure_name,a.overdue_date,a.task_num, a.buss_number, t.inspect_type,t.inspect_ratio,t.should_inspect_num, t.allocation_num ,(t.should_inspect_num - t.allocation_num) as await_num from ${processTableName} a LEFT JOIN t on a.primary_key = t.process_main_id where a.enterprise_code = #{enterpriseCode} and a.delete_flag = false and primary_key in (
#{primaryKey}
)

select *
from ${tableName}
where delete_flag = false
  and enterprise_code = #{enterpriseCode}
  and process_main_id = #{mainId}
